import stories from './story.bs.js';

// Množina u bosanskom: 1 dan, 2 dana, 5 dana
const pl = (n, one, few, many) => {
  const a = Math.abs(n) % 10, b = Math.abs(n) % 100;
  if (a === 1 && b !== 11) return one;
  if (a >= 2 && a <= 4 && (b < 12 || b > 14)) return few;
  return many;
};

