  hinfo: {
    btn: '📘 Znanje o hadžu i umri', title: 'Znanje: hadž i umra',
    next: (d, n) => `Sljedeći hadž: od ${d} · za ${n} ${pl(n, 'dan', 'dana', 'dana')}`,
    tabs: { basics: 'Osnove', pillars: 'Obaveze', days: 'Raspored', ihram: 'Ihram i mikat', medina: 'Medina', prep: 'Priprema', history: 'Historija' },
    basics: [
      'Hadž je peti stub islama: jednom u životu obaveza za svakoga ko to sebi može priuštiti (Kur’an 3:97). Obavlja se samo u određene dane, od 8. do 13. zul-hidždžeta. Umra („mali hadž“) može se obaviti tokom cijele godine i traje samo nekoliko sati: ihram, tavaf, sa’j i šišanje kose.',
      'Hadž postaje obaveza kad si musliman, punoljetan i pri zdravoj pameti, dovoljno zdrav za put, kad imaš novca za put i izdržavanje – i za porodicu koja ostaje kod kuće – i kad je put siguran. Žene po hanefijskom i hanbelijskom mezhebu putuju s mužem ili mahremom; šafijski i malikijski mezheb za obavezni hadž dozvoljavaju i pouzdanu grupu žena. Danas uz to vrijede i pravila Saudijske Arabije.',
      'Umra je po hanefijskom i malikijskom mezhebu naglašeni sunnet, a po šafijskom i hanbelijskom jednom u životu obaveza. Hanefijski mezheb: od 9. do 13. zul-hidždžeta ne započinje se umra.',
      'I dijete može obaviti hadž i za to dobiva nagradu; ali obavezni hadž ostaje na njemu kad postane punoljetno (Muslim).',
    ],
    pillars: [
      'Umra: ihram s nijjetom na mikatu, tavaf (7 krugova oko Kabe), sa’j (7 dionica između Safe i Merve), zatim brijanje ili skraćivanje kose.',
      'Hadž – hanefijski mezheb: farz su ihram, stajanje na Arefatu (vakfa) i tavaful-ifada. Vadžib su, između ostalog, Muzdelifa, sa’j, bacanje kamenčića, brijanje, oprosni tavaf i, kod temettu’a i kirana, kurban.',
      'Hadž – šafijski mezheb: rukni su ihram, vakfa, tavaful-ifada, sa’j i šišanje kose. Malikijski i hanbelijski mezheb: ihram, vakfa, tavaf i sa’j.',
      'Ako nedostaje rukn, hadž nije potpun – bez Arefata nema hadža („Hadž je Arefat“, Tirmizi). Ko izostavi vadžib, to najčešće nadoknađuje kurbanom (dem). Ako nisi siguran: pitaj vodiča grupe ili hodžu.',
      'Tri vrste: ifrad (samo hadž), temettu’ (najprije umra, skidanje ihrama, pa 8. novi ihram za hadž – s kurbanom) i kiran (umra i hadž u jednom ihramu – s kurbanom). Većina hadžija iz inostranstva obavlja temettu’.',
    ],
    days: [
      '8. zul-hidždže (dan tervije): ihram za hadž, odlazak na Minu. Tamo se svaki namaz klanja u svoje vrijeme i noći se.',
      '9. zul-hidždže (dan Arefata): nakon izlaska sunca na Arefat. Podne i ikindija zajedno, zatim stajanje do zalaska sunca – dova, suze, zahvala. Nakon zalaska sunca na Muzdelifu: akšam i jacija zajedno, noć pod vedrim nebom, skupljanje kamenčića.',
      '10. zul-hidždže (Bajram): bacanje kamenčića na veliki stub (Džemretul-Akaba), kurban, šišanje kose – sada je većina toga ponovo dozvoljena. Zatim tavaful-ifada (i sa’j) u Mekki.',
      '11. i 12. zul-hidždže (dani tešrika): boravak na Mini, svaki dan nakon podne po 7 kamenčića na svaki od tri stuba. Ko želi, napušta Minu 12. prije zalaska sunca, inače ostaje do 13.',
      'Na kraju: oprosni tavaf (veda’) prije odlaska iz Mekke.',
    ],
    ihram: [
      'Mikati su granice na kojima se oblači ihram: Zul-Hulejfa (Ebjar Ali) za Medinu, El-Džuhfa (kod Rabiga) za Šam, Egipat, Tursku i Evropu kopnenim putem, Karnul-Menazil za Nedžd, Jelemlem za Jemen, Zatu Irk za Irak. U avionu se mikat najavi – mnogi oblače platna već prije polijetanja, a nijjet donose malo prije mikata.',
      'Muškarci nose dva nešivena bijela platna i sandale koje ostavljaju gornji dio stopala otkrivenim; glava ostaje otkrivena. Žene nose svoju običnu odjeću koja pokriva tijelo, ali bez pokrivanja lica i bez rukavica.',
      'U ihramu je zabranjeno: parfem, šišanje kose i rezanje noktiju, lov, čupanje biljaka u Haremu, svađa i ružne riječi, bračna bliskost, sklapanje braka. „Nema svađe na hadžu“ (Kur’an 2:197) – ihram je i stanje srca.',
      'Žene u hajzu obavljaju sve – telbiju, Arefat, Muzdelifu, bacanje kamenčića –, samo tavaf naknadno obave kad se očiste (Buhari, od Aiše).',
    ],
    medina: [
      'Posjeta Medini nije dio hadža, ali gotovo svi hadžije dolaze tamo. Namaz u Poslanikovoj džamiji (Mesdžidun-Nebevi) bolji je od hiljadu namaza drugdje – osim u Mesdžidul-Haramu (Buhari, Muslim).',
      'Revda, između Poslanikove kuće i minbera, je „bašča od bašči Dženneta“ (Buhari). Za mjesto u njoj danas je potrebna dozvola putem aplikacije Nusuk.',
      'Kod Poslanikovog ﷺ kabura nazovi mu selam tiho i s poštovanjem: „Es-selāmu ʿalejke jā resūla llāh“, zatim Ebu Bekru i Omeru. Druga mjesta: mezarje Bekija, Kuba-džamija – ko u njoj klanja, ima nagradu umre (Ibn Madže) – i brdo Uhud.',
    ],
    prep: [
      'Prijava: putem Islamske zajednice (u BiH i u dijaspori) i ovlaštenih agencija ili – iz Evrope, Amerike i Australije – putem zvanične saudijske platforme Nusuk. Za umru je najčešće dovoljna umra- ili turistička viza. Pravila se mijenjaju: uvijek provjeri aktuelno stanje.',
      'Zdravlje: obavezna je vakcina protiv meningokoka (ACWY); ostale vakcine po savjetu ljekara. U Mekki je često vrlo vruće i gužva – pij mnogo vode, koristi suncobran, odmaraj se, pazi na starije.',
      'Šta spakovati: dva platna za ihram (muškarci), pojas s torbicom, otvorene sandale i udobne cipele, sapun i krema bez mirisa, mala serdžada, boca za vodu, kesica za kamenčiće, lijekovi, punjač, kopija pasoša.',
      'Iznutra: vrati dugove, zamoli za halal sve s kojima si bio u svađi, uredi oporuku, putuj s halal novcem – i idi otvorena srca.',
    ],
    history: [
      'Ibrahim i njegov sin Ismail sagradili su Kabu kao prvu kuću za ibadet Jednom Bogu (Kur’an 2:127). Allah je rekao Ibrahimu: „I oglasi ljudima hadž – dolazit će ti pješice i na iznurenim devama, sa svakog dalekog puta.“ (Kur’an 22:27)',
      'Hadžera, Ismailova majka, u očaju je sedam puta trčala između brežuljaka Safe i Merve tražeći vodu za svoju bebu – i tada je provrio izvor Zemzem. Pri sa’ju hadžije ponavljaju njene korake; bacanje kamenčića podsjeća na to kako se Ibrahim odupro šejtanovim došaptavanjima.',
      'Godine 632. Poslanik ﷺ obavio je svoj jedini hadž, „oprosni hadž“. U svojoj hutbi na Arefatu rekao je: Arap nije bolji od nearapa niti je bijelac bolji od crnca – osim po bogobojaznosti. Zato i danas milioni ljudi iz svih zemalja stoje jedni pored drugih u istom bijelom platnu.',
    ],
    kid: {
      basics: 'Jednom u životu muslimani smiju otputovati u Mekku i obići oko Kabe – to je hadž. Ko nema dovoljno novca ili je bolestan, ne mora. Umra je mali hadž, može se obaviti tokom cijele godine.',
      pillars: 'Na umri ideš sedam puta oko Kabe, zatim sedam puta tamo-amo između dva brežuljka, i na kraju se kosa malo skrati. Na hadžu ima još više – najvažniji je dan na brdu Arefat.',
      days: 'Hadž traje pet dana. Hadžije spavaju u šatorima na Mini, mole na brdu Arefat, spavaju pod zvijezdama na Muzdelifi i bacaju male kamenčiće – kao znak: Ne slušam zlo!',
      ihram: 'Muškarci nose dva bijela platna, žene svoju običnu odjeću. U ihramu se niko ne svađa, ne govori ružne riječi i ne dira ni mušicu ni biljku.',
      medina: 'U Medini je Poslanikova ﷺ džamija sa zelenom kupolom. Tamo hadžije sasvim tiho nazivaju selam Poslaniku i klanjaju u njegovoj džamiji.',
      prep: 'Prije puta zamoliš za oprost sve s kojima si se svađao i spakuješ dva bijela platna, sandale i bocu za vodu.',
      history: 'Hadžera je sedam puta trčala između dva brežuljka da nađe vodu za svoju bebu Ismaila – i onda je provrio izvor Zemzem. Hadžije danas ponavljaju njene korake.',
    },
  },
